\label{D:weak-sol}
Let $q\in [1, \infty)$ and $V$ be a measurable vector field.
We say that a nonnegative measurable function $\rho$ is
a \textbf{$L^q$-weak solution} of \eqref{E:Main}-\eqref{E:Main-bc-ic} with $\rho_0 \in L^{q}(\Omega)$ if the followings are satisfied:
\begin{itemize}
\item[(i)] It holds that
\[
\rho \in L^{\infty}\left(0, T; L^q (\Omega)\right)\cap L^{m} (\Omega_T),\quad \nabla \rho^m \in L^{1}(\Omega_T), \quad \nabla \rho^{\frac{m+q-1}{2}} \in L^{2}(\Omega_T), \quad   \text{and} \quad \rho V \in L^{1}(\Omega_T).
\]
\item[(ii)] For any function $\varphi \in {\mathcal{C}}^\infty_c (\overline{\Omega} \times [0,T))$, it holds that
\begin{equation}\label{KK-May7-40}
\iint_{\Omega_T} \left\{ \rho \varphi_t - \nabla \rho^m \cdot \nabla \varphi + \rho V \cdot \nabla \varphi \right\} \,dx dt = -\int_{\Omega} \rho_{0} (\cdot) \varphi(\cdot, 0) \,dx.
\end{equation}
\end{itemize}

\label{D:Serrin}
Let $m, q \geq 1$ and $q_{m,d} := \frac{d(m-1)}{q}$. For constants $q_1, q_2, \tilde{q}_1, \tilde{q}_2 > 0$, we define following spaces.
\begin{itemize}
\item[(i)]Define
\[
\mathcal{L}_{x,t}^{q_1, q_2}:= \overline{\{V : V \in C_c^\infty(\overline{\Omega} \times[0, T)) ~~\mbox{and}~~ V\cdot \textbf{n} = 0 ~ \mbox{on} ~ \partial \Omega\}}^{L_{x,t}^{q_1, q_2}},
\]
where $\textbf{n}$ is the outward unit normal vector to the boundary of $\Omega$.
That is, the vector field $ V \in \mathcal{L}_{x,t}^{q_1, q_2}$ means that there exists a sequence $V_n  \in C_c^\infty(\overline{\Omega} \times[0, T)) $ such that
$ V\cdot \textbf{n} = 0$ on $\partial \Omega$ and
\[
\|V_n-V \|_{L_{x,t}^{q_1, q_2}} \rightarrow 0 \quad \mbox{as} ~~ n \rightarrow \infty.
\]

\item[(ii)] The \textit{scaling invariant classes} of $V$ and $\nabla  V$ are defined as
\begin{equation}\label{Serrin}
 \mathcal{S}_{m,q}^{(q_1, q_2)}:= \left\{ V \in \mathcal{L}^{q_1, q_2}_{x,t} : \ \|V\|_{\mathcal{L}^{q_1, q_2}_{x,t}} < \infty \ \text{ where } \ \frac{d}{q_1} + \frac{2+q_{m,d}}{q_2} = 1 + q_{m,d} \right\},
\end{equation}
and, for $\tilde{q}^{\ast}_1 = \frac{d \tilde{q}_1}{d-\tilde{q}_1}$ where $\tilde{q}_1 \in (1, d)$, 
\begin{equation}\label{Serrin-grad}
  \tilde{\mathcal{S}}_{m, q}^{(\tilde{q}_1, \tilde{q}_2)}:= 
  \left\{ V \in \mathcal{L}_{x,t}^{\tilde{q}^{\ast}_1, \tilde{q}_2} : 
  \ \|\nabla V\|_{\mathcal{L}^{\tilde{q}_1, \tilde{q}_2}_{x,t}} < \infty  \ \text{ where }  \ \frac{d}{\tilde{q}_1} + \frac{2+q_{m,d}}{\tilde{q}_2} = 2 + q_{m,d}\right\}. 
\end{equation}
Moreover, let us name $\|V\|_{\mathcal{S}_{m,q}^{(q_1, q_2)}}$ and $\|V\|_{\tilde{\mathcal{S}}_{m,q}^{(\tilde{q}_1, \tilde{q}_2)}}$, as the  \textit{scaling invariant norms} corresponding to each spaces.

\item[(iii)] The \textit{sub-scaling classes} are defined as
\begin{equation}\label{subSerrin}
 \mathfrak{S}_{m,q}^{(q_1, q_2)}:= \left\{ V \in  \mathcal{L}^{q_1, q_2}_{x,t} : \ \|V\|_{\mathcal{L}^{q_1, q_2}_{x,t}} < \infty \ \text{ where } \ \frac{d}{q_1} + \frac{2+q_{m,d}}{q_2} \leq 1 + q_{m,d} \right\},
\end{equation}
and, for $\tilde{q}^{\ast}_1 = \frac{d \tilde{q}_1}{d-\tilde{q}_1}$ where $\tilde{q}_1 \in (1, d)$, 
\begin{equation}\label{subSerrin-grad}
  \tilde{\mathfrak{S}}_{m, q}^{(\tilde{q}_1, \tilde{q}_2)}:= \left\{ V \in \mathcal{L}_{x,t}^{\tilde{q}^{\ast}_1, \tilde{q}_2} : 
  \ \|\nabla V\|_{\mathcal{L}^{\tilde{q}_1, \tilde{q}_2}_{x,t}} < \infty  \text{ where }  \frac{d}{\tilde{q}_1} + \frac{2+q_{m,d}}{\tilde{q}_2} \leq 2 + q_{m,d} \right\}.
\end{equation}
Let us name $\|V\|_{\mathfrak{S}_{m,q}^{(q_1, q_2)}}$ and $\|V\|_{\tilde{\mathfrak{S}}_{m,q}^{(\tilde{q}_1, \tilde{q}_2)}}$, as the  \textit{sub-scaling norms} corresponding to each spaces.

\end{itemize}

\label{R:S-tildeS}
\begin{enumerate}
\item[(i)] We remark that the existence results are given under certain assumptions on $V$ in sub-scaling classes. The critical case matters the most and the strict sub-scaling case (the case of strict inequality in \eqref{subSerrin} or \eqref{subSerrin-grad}) is simpler, and therefore, proofs throughout the paper concern only the case of scaling invariant classes.

\item[(ii)] The range of a pair $(q_1, q_2)$ satisfying \eqref{Serrin} is plotted in \cite[Fig. 1]{HKK}. As $m \to 1$ or $q\to \infty$, the constant $q_{m,d}$ becomes $0$, and the conditions in \eqref{Serrin} correspond to 
\begin{equation}\label{linear-Serrin}
V \in L^{q_1, q_2}_{x,t} \quad \text{ where } \quad \frac{d}{q_1} + \frac{2}{q_2} \leq 1,
\end{equation}
which is critical conditions concerning the continuity of \eqref{E:Main} (see, for example, \cite{CHKK17, KZ18, HZ21}). Therefore, the scaling invariant conditions \eqref{Serrin} are more comprehensive for showing correlations of the nonlinear factor $m$ constructing $L^q$-weak solutions, which also includes \eqref{linear-Serrin} as a special case when $m=1$ or $q=\infty$.  
    
\item[(iii)] The equation \eqref{E:Main} is defined on a bounded domain in both spatial and temporal directions; hence, we are able to compute the inequality between two scaling invariant norms. For $1 \leq q \leq q^{L}$, $q_1^L \geq q_1$, and $q_2^L \geq q_2$, it holds that $\mathcal{S}_{m,q}^{(q_1, q_2)} \supseteq \mathcal{S}_{m,q^L}^{(q_1^L, q_2^L)}$ by H\"{o}lder inequalities. 


                                                                                                                                                                                                                         
                              
                                                                                                                                                                               
               

\item[(iv)] Fig. 2 in \cite{HKK} shows the graphs of $(\tilde{q}_1, \tilde{q}_2)$ satisfying 
$\tilde{\mathcal{S}}_{m,q}^{(\tilde{q}_1, \tilde{q}_2)}$ in \eqref{Serrin-grad}. In fact, by using embedding property for $\tilde{q_1} \in (1, d)$, one can suppress the norm of $V$ by the norm of $\nabla V$;  that is,
    $\|V\|_{\mathcal{S}_{m,q}^{(\tilde{q}^{\ast}_{1},  \tilde{q}_2)}} \lesssim  \|V\|_{\tilde{\mathcal{S}}_{m,q}^{(\tilde{q}_1, \tilde{q}_2)}} $
   provided
    \begin{equation}\label{tilde-q2}
    \begin{cases}
    \frac{2+q_{m,d}}{1+{q_{m,d}}} < \tilde{q}_2 \leq \infty, & \text{ if } 1 < m < 1+ \frac{q (d-2)}{d}  \vspace{1 mm}\\
    \frac{2+q_{m,d}}{1+{q_{m,d}}} < \tilde{q}_2 < \frac{2+q_{m,d}}{2-d+q_{m,d}}, & \text{ otherwise}.
    \end{cases}
    \end{equation}
In \cite[Fig. 2]{HKK}, the intersection of lines and shaded region is where \eqref{tilde-q2} holds.
\end{enumerate}

\label{T:weakSol}
Let $m > 1$ and $q\geq 1$.
\begin{itemize}
\item[(i)] Let $1 <m \leq 2$. Assume that $\rho_0 \in  \mathcal{P}(\Omega)$ and $\int_{\Omega} \rho_0 \log \rho_0 \,dx < \infty$ and
\begin{equation}\label{T:weakSol:V_1}
V \in \mathfrak{S}_{m,1}^{(q_1,q_2)} \ \text{ for } \
    \begin{cases}
         2 \leq q_2 \leq  \frac{m}{m-1},  & \text{ if } d > 2 \vspace{1 mm}\\
         2 \leq q_2 <  \frac{m}{m-1},  & \text{ if } d = 2.
    \end{cases}
\end{equation}
Then, there exists a nonnegative $L^1$-weak solution of \eqref{E:Main}-\eqref{E:Main-bc-ic} in Definition~\ref{D:weak-sol}
that holds
 \begin{equation}\label{T:weakSol:E_1}
 \operatorname*{ess \ sup}_{0 \leq t \leq T} \int_{\Omega} \rho \left| \log \rho   \right|(\cdot, t) \,dx
 + \iint_{\Omega_T} \left| \nabla \rho^{\frac{m}{2}} \right|^2 \,dx\,dt
\leq C,
\end{equation}
with $C = C ( \|V\|_{\mathfrak{S}_{m,1}^{(q_1, q_2)}}, \int_{\Omega} \rho_0 \log \rho_0 \,dx)$.

\item[(ii)] Let $q>1$ and $q \geq m-1$.
Assume that $\rho_0 \in  \mathcal{P}(\Omega) \cap L^{q}({ \mathbb{R}  }^d)$ and
\begin{equation}\label{T:weakSol:V_q}
V \in \mathfrak{S}_{m,q}^{(q_1,q_2)} \ \text{ for } \
    \begin{cases}
         2 \leq q_2 \leq  \frac{q+m-1}{m-1},  & \text{ if } d > 2 \vspace{1 mm}\\
         2 \leq q_2 <  \frac{q+m-1}{m-1},  & \text{ if } d = 2.
    \end{cases}
\end{equation}
Then, there exists a nonnegative $L^q$-weak solution of \eqref{E:Main}-\eqref{E:Main-bc-ic} in Definition~\ref{D:weak-sol}
that holds
 \begin{equation}\label{T:weakSol:E_q}
 \operatorname*{ess \ sup}_{0 \leq t \leq T} \int_{\Omega} \rho^q (\cdot, t) \,dx
 + \iint_{\Omega_T} \left| \nabla \rho^{\frac{q+m-1}{2}} \right|^2 \,dx\,dt
\leq C,
\end{equation}
with $C = C ( \|V\|_{\mathfrak{S}_{m,q}^{(q_1, q_2)}}, \|\rho_{0}\|_{L^{q} (\Omega)})$.
\end{itemize}

\label{R:T:energy}
\begin{enumerate}
\item[(i)] Compared to the existence results of \eqref{E:Main} on $\mathbb{R}^d \times [0, T]$ (see \cite[Section~2.1.1]{HKK}), the existence of $L^1$-weak solution in Theorem~\ref{T:weakSol} (i) is new because $p$-th moment estimates are trivial on a bounded domain. The valid range for $(q_1, q_2)$ of \eqref{T:weakSol:V_1} is the line $\overline{\textbf{ED}}$ on Fig.~\ref{F:S:1m2}.

\item[(ii)] Because of energy estimates, there are competing inequalities $q>1$ and $q\geq m-1$ which are sorted into two cases either $q>1$ \& $1<m\leq 2$ or $q\geq m-1$ \& $m>2$. 
The range of $(q_1,q_2)$ satisfying \eqref{T:weakSol:V_q} is illustrated as  $\mathcal{R}(\textbf{abDE})$ in Figs.~\ref{F:S:1m2}, \ref{F:S:1m2:more} or $\mathcal{R}(\textbf{abD})$ in Figs.~\ref{F:S:m2}, \ref{F:S:m2:more} (Figs.~\ref{F:S:1m2:more}, \ref{F:S:m2:more} are in Appendix~\ref{Appendix:fig}).
\end{enumerate}

\label{T:ACweakSol}
Let $m>1$ and $q\geq 1$. Also let $\lambda_q$ be given in \eqref{lambda_q}.
Suppose that $\rho_0 \in
\mathcal{P}(\Omega) \cap L^{q} (\Omega)$.
\begin{itemize}
\item[(i)] Let $1 < m \leq 2$. Suppose that $\rho_0 \in \mathcal{P}(\Omega)$ and $\int_{\Omega} \rho_0 \log \rho_0 \,dx < \infty$ and $V \in \mathfrak{S}_{m,1}^{(q_1,q_2)} $ satisfies \eqref{T:weakSol:V_1}.
Then, there exists a nonnegative $L^1$-weak solution of \eqref{E:Main}-\eqref{E:Main-bc-ic} in Definition~\ref{D:weak-sol} such that  $\rho \in AC(0,T; \mathcal{P} (\Omega))$ with $\rho(\cdot, 0)=\rho_0$.
Furthermore, $\rho$ satisfies
\begin{equation}\label{T:ACweakSol:E_1}
\operatorname*{ess \ sup}_{0\leq t \leq T} \int_{\mathbb{R}^d\times \{t\}} \rho \left| \log \rho \right| (\cdot, t)  \,dx
+ \iint_{\Omega_T} \{ \left| \nabla \rho^{\frac m2} \right|^2 + \left(\left| \frac{\nabla
\rho^m}{\rho} \right|^{\lambda_1}+|V|^{\lambda_1}\right ) \rho  \}\,dx\,dt
 \leq  C,
\end{equation}
and
\begin{equation}\label{T:ACweakSol:W_1}                    
 W_{\lambda_1}(\rho(t),\rho(s))\leq C (t-s)^{\frac{\lambda_1 -1}{\lambda_1}},\qquad
\forall ~~0\leq s\leq t\leq T,
\end{equation}
where the constant $C= C ( \|V\|_{\mathfrak{S}_{m,1}^{(q_1,q_2)}},\,
\int_{\Omega} \rho_0 \log \rho_0 \,dx )$.


  \item [(ii)]  Let $q>1$ and $q\geq m-1$. Assume that
\begin{equation}\label{T:ACweakSol:V_q}
V \in \mathfrak{S}_{m,q}^{(q_1,q_2)} \ \text{ for } \
    \begin{cases}
        q_1 \leq \frac{2m}{m-1}, \  2 \leq q_2 \leq  \frac{q+m-1}{m-1} \,\delta_{\{  1 \leq q \leq m\}} + \frac{2m-1}{m-1}\,\delta_{ \{q > m \} },  & \text{ if } d > 2, \vspace{1 mm}\\
        q_1 \leq \frac{2m}{m-1}, \ 2 \leq q_2 <  \frac{q+m-1}{m-1}\,\delta_{\{1 \leq q \leq m\}} + \frac{2m-1}{m-1} \,\delta_{ \{q > m \} },  & \text{ if } d = 2.
    \end{cases}
\end{equation}
Then, there exists a nonnegative $L^q$-weak solution of \eqref{E:Main}-\eqref{E:Main-bc-ic} in Definition~\ref{D:weak-sol} such that  $\rho \in AC(0,T; \mathcal{P} (\Omega))$ with $\rho(\cdot, 0)=\rho_0$.
Furthermore, $\rho$ satisfies
\begin{equation}\label{T:ACweakSol:E_q}
 \operatorname*{ess \ sup}_{0 \leq t \leq T} \int_{\mathbb{R}^d}  \rho^q  \,dx
 + \iint_{\Omega_T} \{ \left| \nabla \rho^{\frac{q+m-1}{2}}\right |^2 + \left(\left| \frac{\nabla \rho^m}{\rho} \right|^{\lambda_q}+|V|^{\lambda_q}\right ) \rho \} \,dx\,dt \leq C,
\end{equation}
and
\begin{equation}\label{T:ACweakSol:W_q}                    
 W_{\lambda_q} (\rho(t),\rho(s))\leq C (t-s)^{\frac{\lambda_q -1}{\lambda_q}},\qquad
\forall ~~0\leq s\leq t\leq T,
\end{equation}
where $C = C (\|V\|_{\mathfrak{S}_{m,q}^{(q_1, q_2)}}, \, \|\rho_0\|_{L^{q} (\Omega)} )$.

\item[(iii)] (Embedding) Let $q>1$ and $q\geq m-1$. Further assume that $V$ satisfies \eqref{T:weakSol:V_q}. For a pair of constants $(q_1, q_2)$ satisfying \eqref{T:weakSol:V_q}, there exists a pair of constants $(q_1^\ast, q_2^\ast)$ where $V$ belongs $\mathfrak{S}_{m, q^\ast}^{(q_1^{\ast}, q_2^\ast)}$ satisfying \eqref{T:ACweakSol:V_q} for some $q^\ast \in [1, q]$. Furthermore, the same conclusions hold as in (ii) except that $\lambda_q$ is replaced by $\lambda_{q^\ast}$.
\end{itemize}

\label{R:T:ACweakSol}
\begin{itemize}
\item[(i)] To establish an absolutely continuous solution, both energy estimates (\eqref{V-L1-energy} or \eqref{V-Lq-energy} for $1\leq q \leq m$)  and speed estimates (\eqref{V:speed} for $q>m$) are required. Compared to \cite[Theorem~2.9]{HKK}, the results above are same except part (iii) which is more general because now it is possible to apply embedding in both space and time variables. 

\item[(ii)] In Figs.~\ref{F:S:1m2}, \ref{F:S:1m2:more}, dark shaded region $\mathcal{R}(\textbf{CDEFG})$ illustrates the pairs $(q_1, q_2)$ satisfying \eqref{T:ACweakSol:V_q} in case $1 < m \leq 2$ and $q\geq 1$. In case $m>2$ and $q\geq m-1$, dark shaded region $\mathcal{R}(\textbf{CDEG})$ in Figs.~\ref{F:S:m2}, \ref{F:S:m2:more} shows the range of $(q_1, q_2)$ satisfying \eqref{T:ACweakSol:V_q}. 


