In case that $d=3$, if $\frac{15}{13}\le m \le \frac{7}{6}$ and if $\rho_0$ and $c_0$ are non-negative and
\begin{equation}\label{esti-KS150}
\left\Vert \rho_0 \right\Vert_{L^{\infty}(\Omega)}+\left\Vert c_0 \right\Vert_{W^{2,\infty}(\Omega)}<\infty,
\end{equation}
then  there exists a bounded weak solution of
the system \eqref{PME-KS-10}-\eqref{PME-KS-bc}.
\end{itemize}

\label{P:L_r1r2}\cite[Lemma~3.4]{HKK}
 Let $m >1$ and $q \geq 1$. Suppose that
 \begin{equation}\label{rho-space}
 \rho \in L^{\infty}(0, T; L^{q}(\Omega)) \quad \text{and} \quad
 \rho^{\frac{q+m-1}{2}} \in L^{2}(0, T; W^{1,2}(\Omega)).
 \end{equation}
  Then $\rho\in L^{r_1, r_2}_{x, t} (\Omega \times [0, T])$ such that
 \begin{equation}\label{q-r1r2}
 \begin{gathered}
\frac{d}{r_1} + \frac{2+q_{m,d}}{r_2} =
\frac{d}{q}, \quad \text{for} \quad q_{m,d} : = \frac{d(m-1)}{q}, \\
 \text{for} \ \
 \begin{cases}
  q \leq r_1 \leq \frac{d(q+m-1)}{d-2},  \quad q+m-1 \leq r_2 \leq \infty, & \text{ if } \ d > 2, \\
  q \leq r_1 < \infty, \quad q+m-1 < r_2 \leq \infty, &\text{ if }\ d = 2, \\
   q \leq r_1 \leq \infty, \quad q+m-1 \leq r_2 \leq \infty, &\text{ if } \ d= 1.
  \end{cases}
\end{gathered}
\end{equation}
Moreover, there exists a constant $c=c(d)$ such that, for $(d-2)_{+} = \max \{0, d-2\}$,
 \begin{equation}\label{norm-q-r1r2}
\|\rho\|_{L^{r_1, r_2}_{x, t}} \leq c\left(\sup_{0 \leq t \leq T} \int_{\mathbb{R}^d} \rho^{q}(\cdot, t) \,dx\right)^{\frac{1}{r_1} \left[1-\frac{(r_1 - q) (d-2)_{+}}{d(m-1)+2q}\right]} \,
\left\|\nabla \rho^{\frac{q+m-1}{2}} \right\|_{L^{2}_{x,t}}^{\frac{2}{r_2}}
+ \frac{1}{|\Omega|^{1-\frac{1}{r_1}}} \left(\int_{0}^{T} \|\rho(\cdot, t)\|_{L^{1}(\Omega)}^{r_2}\,dt\right)^{\frac{1}{r_2}}.
\end{equation}

\label{Lemma : Arzela-Ascoli} \cite[Proposition 3.3.1]{ags:book}
Let $K  \subset \mathcal{P}_p(\Omega)$ be a sequentially compact set w.r.t the narrow topology.
Let $\sigma_n : [0, T] \rightarrow \mathcal{P} (\Omega)$ be curves such that
\begin{equation*}\label{equi-continuity}
\begin{aligned}
\sigma_n(t) \in K, \quad \forall ~ n &\in \mathbb{N}, ~ t \in [0,T],\\
W_p(\sigma_n(s),\sigma_n(t))&\leq \omega(s,t), \qquad \forall ~
0\leq s\leq t\leq T, ~ n \in \mathbb{N},
\end{aligned}
\end{equation*}
for a continuous function $\omega : [0, T] \times [0, T] \rightarrow [0, \infty)$ such that
$$\omega(t,t)=0, ~~ \forall ~ t \in [0,T].$$
Then there exists a subsequnece $\sigma_{n_k}$ and a limit curve $\sigma : [0,T] \rightarrow {P}_p(\Omega)$ such that
\begin{equation*}\label{eq1 : Lemma : Arzela-Ascoli}
\sigma_{n_k}(t) \mbox{ narrowly converges to} ~~\sigma(t), \qquad
\text{for all} ~~t\in[0, T].
\end{equation*}

\label{Lemma : estimation 1: ODE} \cite[Lemma~3.1]{KK-SIMA}
Let $s\in [0,T]$ and $\psi$ be defined as in \eqref{ODE}. Then, for any $t\in [s,T]$, the map $\psi(t;s,\cdot):\Omega\mapsto \Omega$ satisfies
                                                                            
\begin{equation*}\label{estimation 1: ODE}
e^{-\int_s^t \mbox{Lip}(V(\tau)) \,d\tau}|x-y|\leq |\psi(t;s,x)-\psi(t;s,y)|\leq e^{\int_s^t \mbox{Lip}(V(\tau)) \,d\tau}|x-y| ,
\qquad \forall ~ x,y \in\Omega,
\end{equation*}
where
\[\mbox{Lip}(V(\tau)) := \sup_{x,y \in \Omega , \, x \neq y} \frac{|V(x, \tau) - V(y,\tau)|}{|x-y|}.\]

\label{Lemma : Lipschitz of Jacobian}
Let $s\in [0,T]$ and $\psi$ be defined as in \eqref{ODE}. For any $t\in [s,T]$, let $J_{s,t}$ be the Jacobian corresponding to the map
 $\psi(t;s,\cdot):\Omega\mapsto \Omega$ . That is,
\begin{equation}\label{Jacobian}
\int_{\Omega} \zeta(y) dy:= \int_{\Omega} \zeta(\psi(t;s,x))
J_{s,t}(x)\,dx,\qquad \forall ~\zeta\in C(\Omega) .
\end{equation}
Then, the Jacobian  $ J_{s,t}$ is given as
\begin{equation}\label{Jacobian - formular}
J_{s,t}(x)=e^{\int_s^t \nabla \cdot V (\psi(\tau;s,x),\tau) \,d\tau}, \qquad \forall ~ x\in \Omega.
\end{equation}

Let $x\in \Omega$ be given. Then, we have
\begin{equation*}\label{eq6 : Lipschitz of Jacobian}
\begin{aligned}
\frac{d}{dt} J_{s,t}(x)\big |_{t=\tau}& =\nabla \cdot V(\psi(\tau;s,x), \tau)J_{s,\tau}(x).    
                                                                             
                                                                                         
\end{aligned}
\end{equation*}
                                                   
Since $J_{s,s}\equiv 1$, we have
\begin{equation}\label{eq7 : Lipschitz of Jacobian}
\log J_{s,t}(x) = \int_s^t \nabla \cdot V( \psi(\tau;s,x),\tau)
\,d\tau.
\end{equation}
This completes the proof.

We note that $\psi(t;s,\cdot) \circ \psi(s;t,\cdot) = Id $, that is,
$$ \psi(t;s, \psi(s; t, x)) = x,  \quad \forall ~ x\in \Omega. $$
Exploiting this, we have
\begin{equation*}
J_{s,t}(\psi(s;t,x )) = \frac{1}{J_{t,s}(x)}.
\end{equation*}

\label{Corollary-4:Lipschitz}\cite[Lemma~3.3]{KK-SIMA}
Let $s\in [0,T]$ and $\Psi$ be  in \eqref{Flow on Wasserstein}. For any $t\in [s,T]$ and $\mu,\nu\in \mathcal{P}_p (\Omega)$,
we have
\begin{equation}\label{eq1:Corollary-4:Lipschitz}
e^{-\int_s^t \mbox{Lip}(V(\tau)) \,d\tau}W_p(\mu,\nu)\leq W_p(\Psi(t;s,\mu),\Psi(t;s,\nu))\leq e^{\int_s^t \mbox{Lip}(V(\tau)) \,d\tau}W_p(\mu,\nu).
\end{equation}

\label{Lemma : Holder regularity on the flow}\cite[Lemma~3.18]{HKK}
Let $\psi$ and $\Psi$ be defined as in \eqref{ODE} and \eqref{Flow on
Wasserstein}, respectively. Suppose that $V \in  L^1(0,T;W^{1,\infty}(\Omega))$.
\begin{itemize}
\item[(i)] If $V \in L^1(0,T;  { \mathcal C  }^{1, \alpha}(\Omega)) $ and $\varrho\in
\mathcal{P}_p(\Omega) \cap { \mathcal C  }^\alpha (\Omega)$ for some $\alpha \in (0,1)$,
then $\rho:=\Psi(t;s,\varrho)$ is also H\"{o}lder continuous. More
precisely, we have $\| \rho\|_{{ \mathcal C  }^\alpha (\Omega)} < C $ where $C=C(\| \varrho\|_{{ \mathcal C  }^\alpha (\Omega)},\, \int_s^t \|\nabla V \|_{{ \mathcal C  }^\alpha (\Omega)} d\tau )$.
                         
                                                                  
                                       
                                       
                
                                                                                                                 
\item[(ii)] If $V \in L^1(0,T;  W^{2, \infty}(\Omega)) $, then, for any  $a>0,~ q\geq 1$, we have
\begin{equation}\label{eq5 : Sobolev}
\begin{aligned}
 \|\nabla \rho^a\|_{L^q (\Omega)}&\leq e^{(a+2)\int_s^t \|\nabla V\|_{L^\infty_x}\, d\tau}\left \{ \|\nabla \varrho^a\|_{L^q (\Omega)} + \| \varrho^{a}\|_{L^p_x}
 \times \left ( a\int_s^t \| \nabla^2 V\|_{L^\infty_x} \,d\tau\right ) \right \}.
\end{aligned}
\end{equation}
\end{itemize}

\label{P:Lq-energy}
Let $m> 1$ and $q\geq 1$. Suppose that $\rho$ is a regular solution of \eqref{E:Main}-\eqref{E:Main-bc-ic} with $\rho_{0}\in  L^{q}(\Omega) \cap { \mathcal C  }^{\alpha}(\overline{\Omega})$.
           
                                   
                                                                       
               
\begin{itemize}

\item[(i)] Let $1 < m \leq 2$. Assume $\int_{\Omega} \rho_0 \log \rho_0 \,dx < \infty$ and
\begin{equation}\label{V-L1-energy}
V \in \mathcal{S}_{m,1}^{(q_1,q_2)}\cap { \mathcal C  }^{\infty} (\overline{\Omega}_{T}) \quad  \text{for} \quad
\begin{cases}
2 \leq q_2 \leq \frac{m}{m-1},  & \text{ if } d> 2, \vspace{1 mm}\\
2\leq q_2 < \frac{m}{m-1},  & \text{ if } d= 2.
\end{cases}
\end{equation}
Then the following estimate holds:
\begin{equation}\label{L1-energy}
 \sup_{0 \leq t \leq T}  \int_{\Omega \times \{t\}} \rho \left| \log \rho \right| (\cdot, t)\,dx
 +  \frac{2}{m}\iint_{\Omega_T} \left|\nabla \rho^{\frac{m}{2}}\right|^2 \,dx\,dt \le C ,
\end{equation}
where  $C = C (\|V\|_{\mathcal{S}_{m,1}^{(q_1, q_2)}}, \, \int_{\Omega} \rho_0 \log \rho_0 \,dx)$.


\item[(ii)] Let $q>1$ and $q \geq m-1$. Assume that
\begin{equation}\label{V-Lq-energy}
V \in \mathcal{S}_{m,q}^{(q_1,q_2)}\cap { \mathcal C  }^{\infty} (\overline{\Omega}_{T}) \quad  \text{for} \quad
\begin{cases}
2 \leq q_2 \leq \frac{q+m-1}{m-1},  & \text{ if } d> 2, \vspace{1 mm}\\
2\leq q_2 < \frac{q+m-1}{m-1},  & \text{ if } d= 2.
\end{cases}
\end{equation}
Then the following estimate holds:
\begin{equation}\label{Lq-energy}
 \sup_{0 \leq t \leq T}  \int_{\Omega \times \{t\}} \rho^{q} (\cdot, t)\,dx
 + \frac{2 q m (q-1)}{(q+m-1)^2} \iint_{\Omega_T} \left|\nabla \rho^{\frac{q+m-1}{2}}\right|^2 \,dx\,dt \le C ,
\end{equation}
where  $C = C (\|V\|_{\mathcal{S}_{m,q}^{(q_1, q_2)}}, \, \|\rho_{0}\|_{L^{q} (\Omega)})$.

\item[(iii)]  Assume that
 \begin{equation}\label{V-tilde-Lq}
V\in \tilde{\mathcal{S}}_{m,q}^{(\tilde{q}_1, \tilde{q}_2)} \cap { \mathcal C  }^{\infty} (\overline{\Omega}_{T}) \quad  \text{for} \quad
\begin{cases}
1 \leq \tilde{q}_2 \leq \frac{q+m-1}{m-1},   & \text{ if } d> 2, \vspace{1 mm}\\
1\leq \tilde{q}_2 < \frac{q+m-1}{m-1},  & \text{ if } d= 2 .
\end{cases}
\end{equation}
$\bullet$ In case $q=1$, assume $\int_{\Omega} \rho_0 \log \rho_0 \,dx < \infty$. Then \eqref{L1-energy} holds with $C = C (\|V\|_{\tilde{\mathcal{S}}_{m,1}^{(\tilde{q}_1, \tilde{q}_2)}}, \, \int_{\Omega} \rho_0 \log \rho_0 \,dx )$.\\
$\bullet$ In case $q>1$, the estimate \eqref{Lq-energy} holds with
$C = C (\|V\|_{\tilde{\mathcal{S}}_{m,q}^{(\tilde{q}_1, \tilde{q}_2)}}, \, \|\rho_{0}\|_{L^{q} (\Omega)})$.

\item[(iv)]  Assume that $V\in{ \mathcal C  }^{\infty} (\overline{\Omega}_{T})$ and $\nabla\cdot V \geq 0$.\\
$\bullet$ In case $q=1$, assume $\int_{\Omega} \rho_0 \log \rho_0 \,dx < \infty$. Then \eqref{L1-energy} holds with $C = C (\int_{\Omega} \rho_0 \log \rho_0 \,dx )$.\\
$\bullet$ In case $q>1$, the estimate \eqref{Lq-energy} holds with $C = C ( \|\rho_{0}\|_{L^{q} (\Omega)})$.
\end{itemize}

When $q=1$, we obtain the following estimate by testing $\log \rho$ to \eqref{E:Main}:
\begin{equation}\label{Elog-0}
\frac{d}{dt} \int_{\Omega} \rho \log \rho \,dx +  \frac{4}{m}\int_{\Omega} \left|  \nabla \rho^{\frac{m}{2}} \right|^2\,dx =  \underbrace{\int_{\Omega} V \cdot \nabla \rho \,dx}_{ =: \mathcal{J}_1},
\end{equation}
because of the followings:
\[\begin{gathered}
\int_{\Omega} \rho_t \log \rho \,dx =  \frac{d}{dt} \int_{\Omega} (\rho \log\rho - \rho) \,dx = \frac{d}{dt} \int_{\Omega} \rho \log\rho \,dx, \\
\int_{\Omega} \nabla \cdot (\nabla \rho^m - V\rho) \log \rho \,dx 
=  - \int_{\Omega} \left(\nabla \rho^m \nabla \log \rho - V \rho \nabla \log \rho \right) \,dx,
\end{gathered}\]
because of the mass conservation property and the boundary condition \eqref{E:Main-bc-ic}.

Now let $q > 1$. By testing $\varphi = q \rho^{q-1}$ to \eqref{E:Main}, we have
\begin{equation}\label{apriori2-eqn}
  \frac{d}{dt} \int_{\Omega} \rho^{q}\,dx
+ \frac{4m q (q-1)}{(q+m-1)^2} \int_{\Omega} \left| \nabla\rho^{\frac{q+m-1}{2}} \right|^2\,dx
 =  \underbrace{(q-1) \int_{\Omega} V \cdot \nabla \rho^{q}\,dx}_{=: \mathcal{J}_q},
\end{equation}
because of the followings: 
\[\begin{gathered}
\int_{\Omega} q \rho^{q-1} \rho_t\,dx =  \frac{d}{dt} \int_{\Omega} \rho^q \,dx, \\	
q\int_{\Omega} \nabla \cdot (\nabla \rho^m - V\rho) \rho^{q-1} \,dx
= - q\int_{\Omega} \left(\nabla \rho^m \nabla \rho^{q-1} - V \rho \nabla \rho^{q-1} \right) \,dx,
\end{gathered}\]
because of the boundary conditions \eqref{E:Main-bc-ic}.

\smallskip

(i) With the estimate \eqref{Elog-0}, we observe that, for  $1 - \frac m2 \geq 0$ (equivalent to $1 < m \leq 2$),
\begin{equation}\label{energy-V-0}
\mathcal{J}_{1} = \frac{2}{m} \int_{\Omega} V \rho^{1-\frac{m}{2}} \nabla \rho^{\frac m 2} \,dx \leq c  \|V\|_{L^{q_1}_{x}}
  \left\|\nabla \rho^{\frac{m}{2}}\right\|_{L^{2}_{x}}
 \|\rho\|_{L_{x}^{\frac{q_1 m }{q_1 -2}}}^{\frac{m}{2}},
\end{equation}
by taking H\"{o}lder inequality with $\frac{1}{q_1} + \frac{1}{2} + \frac{q_1 -2 }{2q_1} = 1$ for $q_1 > 2$. When $m=2$, we follow \eqref{energy-V2}. Moreover, we denote same settings in \eqref{energy00.4} and \eqref{energy00.5} for $q=1$. Then the same computation in \eqref{energy01} with $\varepsilon = \frac{2}{m}$ provides the following estimate:
\begin{equation}
\frac{d}{dt} \int_{\Omega} \rho \log \rho \,dx +  \frac{2}{m}\int_{\Omega} \left|  \nabla \rho^{\frac{m}{2}} \right|^2\,dx
\leq c \|V\|_{L^{q_1}_{x}}^{q_2} \left(\|\rho\|_{L_{x}^{1}} + 1\right) + c
\end{equation}
for $q_2$ in \eqref{energy02} for $q=1$. The estimate \eqref{Lq-energy} is obtained by taking the integration in terms of $t\in [0, T]$ and applying that the negative part of $\int_{\Omega} \rho \log \rho \,dx < \infty$ because $\Omega$ is bounded and
$\|\rho(\cdot, t)\|_{L^{1}_{x}} = 1$ because of the mass conservation property.


(ii) In case $q>1$ and $q \geq m-1$, we observe that
\begin{equation}\label{energy-V-1}
\mathcal{J}_{q} = \frac{2(q-1)}{q+m-1}\int_{\Omega} V \rho^{\frac{q-m+1}{2}} \nabla \rho^{\frac{q+m-1}{2}}\,dx.
\end{equation}

When $q=m-1$ (in particular, $m=2$ if $q=1$), we have
\begin{equation}\label{energy-V2}
\mathcal{J}_q \leq c  \int_{\mathbb{R}^d} |V| \left| \nabla \rho^{\frac{q+m-1}{2}} \right|\,dx
\leq c \|V\|_{L^{2}_{x}}
  \left\|\nabla \rho^{\frac{m+q-1}{2}}\right\|_{L^{2}_{x}}
  \leq \varepsilon  \left\|\nabla \rho^{\frac{m+q-1}{2}}\right\|_{L^{2}_{x}}^{2}
  + c(\varepsilon ) \|V\|_{L^{2}_{x}}^{2}.
\end{equation}
Now, let $q > m-1$ for all $q\geq 1$. Then by H\"{o}lder inequality with $\frac{1}{q_1} + \frac{1}{2} + \frac{q_1 -2 }{2q_1} = 1$ for $q_1 > 2$, we have
\begin{equation*}\label{energy00}
\mathcal{J}_q \leq c \int_{\Omega} |V| \rho^{\frac{q-m+1}{2}} \left| \nabla \rho^{\frac{q+m-1}{2}} \right|\,dx
\leq  c  \|V\|_{L^{q_1}_{x}}
  \left\|\nabla \rho^{\frac{m+q-1}{2}}\right\|_{L^{2}_{x}}
 \|\rho\|_{L_{x}^{\frac{q_1 (q-m+1)}{q_1 -2}}}^{\frac{q-m+1}{2}}.
\end{equation*}
For simplicity, let
\begin{equation}\label{energy00.4}
    r_1 := \frac{q_1 (q-m+1)}{q_1 -2}, \quad \text{and} \quad \theta := \frac{q}{r_1} \left( 1 - \frac{(r_1 - q)(d-2)}{2q + d(m-1)}\right).
\end{equation}
Then by \eqref{q-r1r2} in Lemma~\ref{P:L_r1r2}, we see that
\begin{equation}\label{energy00.5}
\begin{cases}
     2<\frac{d(q+m-1)}{q+(d-1)(m-1)}\leq q_1 \leq \frac{2q}{m-1}, & \text{ if } d>2, \vspace{1 mm}\\
     2< q_1 \leq \frac{2q}{m-1}, & \text{ if } d = 2.
\end{cases}
\end{equation}
Then by modifying interpolation inequalities in Lemma~\ref{P:L_r1r2} for $\Omega \Subset { \mathbb{R}  }^d$, we deduce
\begin{equation}\label{energy01}
\begin{aligned}
\mathcal{J}_q
&\leq c     \|V\|_{L^{q_1}_{x}}
  \left\|\nabla \rho^{\frac{m+q-1}{2}}\right\|_{L^{2}_{x}}
 \left(\left\|\nabla \rho^{\frac{m+q-1}{2}}\right\|_{L^{2}_{x}}^{\frac{(1-\theta)(q-m+1)}{q+m-1}}
 \|\rho\|_{L_{x}^{q}}^{\frac{\theta(q-m+1)}{2}} + \|\rho\|_{L_{x}^{1}}^{\frac{q+m-1}{2}}\right) \\
&\leq \varepsilon \left\|\nabla \rho^{\frac{m+q-1}{2}}\right\|_{L^{2}_{x}}^{2}
 +c(\varepsilon) \left( \|V\|_{L^{q_1}_{x}}^{q_2}\|\rho\|_{L_{x}^{q}}^{q_2 \frac{\theta(q-m+1)}{2}} + c\|V\|_{L^{q_1}_{x}}^{2}\right) \\
&\leq \varepsilon \left\|\nabla \rho^{\frac{m+q-1}{2}}\right\|_{L^{2}_{x}}^{2}
 +c(\varepsilon) \|V\|_{L^{q_1}_{x}}^{q_2} \left(\|\rho\|_{L_{x}^{q}}^{q_2 \frac{\theta(q-m+1)}{2}} + 1\right) + c(\varepsilon) \\
 &\leq \varepsilon \left\|\nabla \rho^{\frac{m+q-1}{2}}\right\|_{L^{2}_{x}}^{2}
 +c(\varepsilon) \|V\|_{L^{q_1}_{x}}^{q_2} \left(\|\rho\|_{L_{x}^{q}}^{q} + 1\right) + c(\varepsilon)
\end{aligned}
\end{equation}
by taking Young's inequality (note that $q_2 \geq 2$). Due to $V\in \mathcal{S}_{m,q}^{(q_1,q_2)}$, it gives
\begin{equation}\label{energy02}
 \frac{2(q+m-1)}{(q+m-1)-(1-\theta)(q-m+1)} = \frac{q_1 (2+q_{m,d})}{q_1 (1+q_{m,d}) - d} =  q_2.
\end{equation}
The conditions \eqref{energy00.5} corrresponds to \eqref{V-Lq-energy}.


For $q>1$, we combine \eqref{apriori2-eqn} and \eqref{energy01} with $\varepsilon = \frac{4mq(q-1)}{(q+m-1)^2}$ that yields
\begin{equation}\label{energy03}
    \frac{d}{dt} \int_{\Omega} \rho^{q}\,dx \leq c \|V\|_{L^{q_1}_{x}}^{q_2} (\|\rho\|_{L_{x}^{q}}^{q} + 1) + c \quad \Longrightarrow \quad
    \sup_{0\leq t \leq T} \int_{\Omega \times \{t\}} \rho^{q}\,dx
    \leq C \int_{\Omega} \rho_{0}^{q}\,dx + C,
\end{equation}
where $C= C(\|V\|_{\mathcal{S}_{m,q}^{(q_1, q_2)}})$ by Gr\"{o}nwall's inequality.
When $q=1$, it is obvious because of the mass conservation property.
Now we take the integration in terms of $t$ after combining estimates \eqref{apriori2-eqn} and \eqref{energy01}  which yields
\begin{equation}\label{energy05}
\begin{aligned}
\sup_{0\leq t\leq T} \int_{\Omega \times \{t\}} \rho^{q}\,dx
&+ \frac{2m q (q-1)}{(q+m-1)^2} \iint_{\Omega_T} \left| \nabla\rho^{\frac{q+m-1}{2}} \right|^2\,dx\,dt \\
&\leq \int_{\Omega} \rho_{0}^{q}\,dx
+ c \|V\|_{\mathcal{S}_{m,q}^{(q_1, q_2)}}\sup_{0\leq t \leq T}\|\rho (\cdot, t)\|_{L_{x}^{q}(\Omega)}^{q_2 \frac{\theta(q-m+1)}{2}}.
\end{aligned}
\end{equation}
Therefore, we obtain \eqref{Lq-energy} by substituting \eqref{energy03} into \eqref{energy05}.
                                                                                                                               
\smallskip

(iii) In this case, we take the integration by parts that gives, due to $V\cdot \textbf{n} = 0$ on $\partial \Omega$,
\begin{equation}\label{energy-V-2}
\mathcal{J}_{1} =  - \int_{\Omega} \rho \, \nabla \cdot V \,dx,
\quad \text{and} \quad
\mathcal{J}_{q} = -(q-1) \int_{\Omega} \rho^q \, \nabla \cdot V \,dx.
\end{equation}
By taking H\"{o}lder inequality with $\frac{1}{\tilde{q}_1} + \frac{\tilde{q}_1 -1}{\tilde{q}_1} = 1$ for $\tilde{q}_1 > 1$, we have
 \begin{equation*}
 \mathcal{J}_1 , \, \mathcal{J}_{q} \leq c \|\nabla  V\|_{L_{x}^{\tilde{q}_1}} \|\rho\|_{L^{\frac{q \tilde{q}_1}{\tilde{q}_1 -1}}_{x}}^{q}.
 \end{equation*}
 For simplicity, let
 \begin{equation*}
 \tilde{r}_1 := \frac{q\tilde{q}_1}{\tilde{q}_1 - 1} \quad \text{ and } \quad \theta := \frac{q}{\tilde{r}_1} \left( 1 - \frac{(\tilde{r}_1 - q)(d-2)}{2q+d(m-1)} \right).
 \end{equation*}
Then by \eqref{q-r1r2} in Lemma~\ref{P:L_r1r2} for $\tilde{r}_1$ instead of $r_1$, it gives
 \begin{equation}\label{energy06}
 \begin{cases}
  1<\frac{d+q_{m,d}}{2+q_{m,d}}\leq \tilde{q}_1 \leq \infty, & \text{ if } d>2, \vspace{1 mm}\\
  1< \tilde{q}_1 \leq \infty, & \text{ if } d= 2.
  \end{cases}
 \end{equation}


 Then by Lemma~\ref{P:L_r1r2}, we deduce
 \begin{equation}\label{energy07}
 \begin{aligned}
 \mathcal{J}_1 , \, \mathcal{J}_{q}
 &\leq c \|\nabla V\|_{L_{x}^{\tilde{q}_1}} \left(\|\rho\|_{L^{q}_{x}}^{q\theta}
 \left\|\nabla \rho^{\frac{q+m-1}{2}}\right\|_{L^{2}_{x}}^{\frac{2q(1-\theta)}{q+m-1}} + \|\rho\|^{q}_{L^1_x} \right)\\
 &\leq \varepsilon \left\|\nabla \rho^{\frac{q+m-1}{2}}\right\|_{L^{2}_{x}}^{2}
 + c(\varepsilon) \|\nabla V\|_{L_{x}^{\tilde{q}_1}}^{\tilde{q}_2} \left( \|\rho\|_{L^{q}_{x}}^{q\theta \tilde{q}_2} + 1 \right) \\
  &\leq \varepsilon \left\|\nabla \rho^{\frac{q+m-1}{2}}\right\|_{L^{2}_{x}}^{2}
 + c(\varepsilon) \|\nabla V\|_{L_{x}^{\tilde{q}_1}}^{\tilde{q}_2} \left( \|\rho\|_{L^{q}_{x}}^{q} + 1 \right),
 \end{aligned}
 \end{equation}
 by taking Young's inequality. Because of $V \in \tilde{\mathcal{S}}_{m,q}^{(\tilde{q}_1, \tilde{q}_2)}$, it gives
 \begin{equation*}
  \frac{q+m-1}{(q+m-1)-(1-\theta)q}  = \frac{\tilde{q}_1 (2+q_{m,d})}{\tilde{q}_1 (2+q_{m,d}) - d} =  \tilde{q}_2.
 \end{equation*}
 Also, we observe that \eqref{energy06} corresponds to \eqref{V-tilde-Lq}.

Then we combine \eqref{apriori2-eqn} and \eqref{energy07} with $\varepsilon = \frac{4mq(q-1)}{(q-m+1)^2}$ which yields
\begin{equation}\label{energy08.5}
    \sup_{0 \leq t \leq T} \int_{\Omega} \rho^q (\cdot, t)\,dx
    \leq c \|\nabla V\|_{L_{x}^{\tilde{q}_1}}^{\tilde{q}_2} \left( \|\rho\|_{L^{q}_{x}}^{q} + 1 \right)
    \quad \Longrightarrow \quad
    \sup_{0\leq t \leq T} \int_{\Omega \times \{t\}} \rho^{q}\,dx
    \leq C \int_{\Omega} \rho_{0}^{q}\,dx + C
\end{equation}
where $C=C(\|\nabla \cdot V\|_{\tilde{\mathcal{S}}_{m,q}^{(\tilde{q}_1, \tilde{q}_2)}})$ by applying Gr\"{o}nwall's inequality. Now, the estimate \eqref{Lq-energy} follows by applying \eqref{energy08.5} to the estimate obtained by taking integration in terms of $t$ to the combination of \eqref{apriori2-eqn} and \eqref{energy07}.

(iv) In \eqref{energy-V-2}, we observe that $\mathcal{J} \leq 0$ for all $q\geq 1$ when $\nabla \cdot V \geq 0$. Hence we obtain \eqref{Lq-energy} with $C$ depending only the domain and initial data.

