\item[(iii)]  For $q \geq 1$
\begin{equation}\label{KK-Feb19-100}
                                                              
\int_0^T \|\nabla \rho^{\frac{m+q-1}{2}}\|_{L^2_x}^2 dt \leq  C,
\end{equation}
where the constant $C=C\left (\|\rho_0\|_{L^{m+q-1}(\Omega)},~~
\|V\|_{L^1(0,T;W^{2,\infty}(\Omega))} \right )$.


\item[(iv)] For all $t\in [0, T]$ and $q\in[1, \infty]$, we have
\begin{equation}\label{KK-Nov24-100}
\|\rho(t)\|_{L^q_x} \leq \|\rho_0\|_{L^q(\Omega)}e^{\frac{q-1}{q}\int_0^T
\|\nabla \cdot V \|_{L^\infty_x} \,d\tau} ,                             
\end{equation}
where $\frac{q-1}{q}=1$ if $q=\infty$.
\end{itemize}

\label{Lemma:AC-curve}\cite[Lemma 5.4]{HKK}
Let $V \in L^1(0,T : W^{1,\infty}(\Omega))$ with  $V\cdot\mathbf{n}=0$ on $\partial \Omega$      and $\rho_0 \in \mathcal{P}_2(\Omega) \cap  \mathcal{C}^\alpha(\Omega)$ for some $\alpha \in (0,1)$.
Suppose that $\rho_n,\varrho_n:[0,T]\mapsto \mathcal{P}_2(\Omega)$ are curves defined as above with the initial data $\varrho_n(0),\rho_n(0):=\rho_0 $.
Then, these curves satisfy the following properties;
\begin{itemize}
\item[(i)] For all $t\in [0,T],$ we have
\begin{equation}\label{eq29:Lemma:AC-curve}
\|\varrho_{n}(t)\|_{L^q_x}, \  \|\rho_{n}(t)\|_{L^q_x} \leq \|\rho_0\|_{L^q(\Omega)}
e^{\frac{q-1}{q}\int_0^T \|\nabla \cdot V\|_{L^\infty_x} \,d\tau}, \qquad \forall ~  q \geq 1.
\end{equation}

\item[(ii)] For all $s,t \in [0,T],$ we have
\begin{equation}\label{eq20:Lemma:AC-curve}
\begin{aligned}
W_2(\rho_{n}(s), \rho_{n}(t)) &\leq C \sqrt{t-s}+ \int_s^t \|V(\tau)\|_{L^\infty_x} \,d\tau  ,
\end{aligned}
\end{equation}
where $C= C(\int_0^T \|\nabla V\|_{L^\infty_x}  \,d\tau , \|\rho_0\|_{L^m (\Omega)})$

\item[(iii)] For all $t \in [0,T],$ we have
\begin{equation}\label{eq21:Lemma:AC-curve}
\begin{aligned}
W_2(\rho_{n}(t), {\varrho}_{n}(t)) \leq  \max_{\{i=0,1,\dots,n\}}\int_{\frac{iT}{n}}^{\frac{(i+1)T}{n}} \|V(\tau)\|_{L^\infty_x} \,d\tau.
\end{aligned}
\end{equation}

\end{itemize}

\label{Lemma:H-curve}\cite[Lemma 5.5 and Lemma 5.6]{HKK}
Let $V \in L^1(0,T : W^{2,\infty}(\Omega)) \cap C^\infty(\overline{\Omega}_T)$ with $V\cdot\mathbf{n}=0$ on $\partial \Omega$ and $\rho_0 \in \mathcal{P}_2(\Omega)\cap \mathcal{C}^\alpha(\Omega)$ for some $\alpha \in (0,1)$.
Suppose that $\rho_n,\varrho_n:[0,T]\mapsto
\mathcal{P}_2(\Omega)$ are curves defined as in Lemma
\ref{Lemma:AC-curve} with the initial data
$\varrho_n(0),\rho_n(0):=\rho_0$. Then, we have
\begin{equation}\label{main : Lemma:H-curve}
\int_0^T \|\nabla \varrho_{n}^{\frac{m+q-1}{2}}\|_{L^2_x}^2 dt + \int_0^T \|\nabla (\rho_{n})^{\frac{m+q-1}{2}}\|_{L^2_x}^2 dt\leq C
\left(\|\rho_0\|_{L^{m+q-1}(\Omega)}, ~\| V\|_{ L^1(0,T : W^{2,\infty}(\Omega))}\right), \quad \forall \ q \geq 1.
\end{equation}

\label{Lemma:solving ODE}\cite[Lemma 5.7]{HKK}
Let $\varphi \in { \mathcal C  }_c^\infty(\overline{\Omega} \times [0,T))$ and
$\rho_n,\varrho_n:[0,T]\mapsto \mathcal{P}_2(\Omega)$ be the
curves defined as in Lemma \ref{Lemma:AC-curve}. For any $s,~t \in
[0,T]$, we define
\begin{equation*}
\begin{aligned}
E_n &:= \int_{\Omega}\varphi(x,t) ~\rho_n(x,t)\,dx - \int_{\Omega}\varphi(x,s) ~\rho_n(x,s)\,dx\\
  &\quad  - \int_{s}^{t} \int_{\Omega}  ( \nabla   \varphi \cdot V) ~\rho_n \,dx \,d\tau
  - \int_{s}^{t}
\int_{\Omega}  \{ \partial_\tau \varphi ~ \varrho_n - \nabla \varphi \cdot \nabla (\varrho_n)^m \}\,dx \,d\tau.
\end{aligned}
\end{equation*}
Then,
\begin{equation*}
\begin{aligned}
|E_n| \leq  C\frac{T}{n}\|\varphi\|_{{ \mathcal C  }^2} e^{C\int_{s}^{t}\|\nabla V\|_{L^\infty_x} \,d\tau}
 \int^{t}_{0} \|V (\tau)\|_{W^{1,\infty}_x} \,d\tau  \longrightarrow 0, \quad as \quad n\rightarrow \infty,
\end{aligned}
\end{equation*}
where $C$ is the same constant in Lemma \ref{Lemma:AC-curve}.

\label{Lemma : equi-continuity}
Let $\tilde{\alpha}\in (0,1)$ be the constant in Theorem \ref{T:Boundary_Holder}. Suppose that $ \alpha \in (0, \tilde{\alpha}]$ and
\begin{equation*}
\rho_0 \in \mathcal{P}_2(\Omega) \cap { \mathcal C  }^\alpha (\Omega)  \quad \mbox{and} \quad V \in  L^1(0,T ; { \mathcal C  }^{1, \alpha}(\Omega))
\end{equation*}
with  $V\cdot\mathbf{n}=0$ on $\partial \Omega$.
Let $\rho_n,\varrho_n:[0,T]\mapsto \mathcal{P}_2(\Omega)$ be curves defined as in Lemma \ref{Lemma:AC-curve}.
                                                                                                                                                                    
Then,we have
 \begin{equation}\label{eq 2 : Holder of splitting}
|\varrho_n(x,t)-\varrho_n(y,t)| + |\rho_n(x,t)-\rho_n(y,t)|\leq C|x-y|^\alpha,  \qquad \forall ~ x, y \in \Omega , ~ t \in [0, T],
 \end{equation}
                                                               
  where $C(\|\rho_0\|_{L^\infty(\Omega)},  \int_0^T \|\nabla V\|_{{ \mathcal C  }^\alpha (\Omega)}  \,d\tau)$.

First, we suppose $t \in \left[0, \frac{T}{n}\right]$.                                                                                  
Due to Theorem \ref{T:Boundary_Holder}, it holds
                                                 
\begin{equation}\label{eq 1 : Lemma equi-cont}
|\varrho_n(x,t)-\varrho_n(y,t) |\leq C |x-y|^\alpha,  \quad \forall ~ x, ~y \in \Omega,
\end{equation}
where $C= C(\|\rho_0 \|_{L^\infty(\Omega)})$.
Next, due to Lemma \ref{Lemma : Holder regularity on the flow}, we have
\begin{equation}\label{eq 2 : Lemma equi-cont}
|\rho_n(x,t)-\rho_n(y,t) | \leq C |x-y|^{\alpha}, \quad   \forall ~x, ~ y \in \Omega,
\end{equation}
where $C= C \left(\text{sup}_{t \in \left[0, \frac{T}{n}\right ]} \|\varrho_n(t)\|_{{ \mathcal C  }^\alpha (\Omega)}, \,\int_0^{T/n} \|\nabla V \|_{{ \mathcal C  }^\alpha (\Omega)} \,d\tau \right)$.


We combine \eqref{eq 1 : Lemma equi-cont} and \eqref{eq 2 : Lemma equi-cont}, and exploit \eqref{eq29:Lemma:AC-curve} for $q=\infty$ to conclude
 \begin{equation}\label{eq 3 : Lemma equi-cont}
|\varrho_n(x,t)-\varrho_n(y,t)|+ |\rho_n(x,t)-\rho_n(y,t)|\leq C|x-y|^\alpha,  \qquad \forall ~x, ~ y \in \Omega ,
 \end{equation}
where $C(\|\rho_0\|_{L^\infty(\Omega)}, ~ \int_0^{T/n} \|\nabla V \|_{{ \mathcal C  }^\alpha (\Omega)} \,dt)$.

For the general case $t \in \left [\frac{iT}{n}, \frac{(i+1)T}{n}\right ], ~ i=1, 2, \dots, n-1$, we repeat what we did in the first step and get
 \begin{equation}\label{eq 4 : Lemma equi-cont}
|\varrho_n(x,t)-\varrho_n(y,t)| +|\rho_n(x,t)-\rho_n(y,t)|\leq C|x-y|^\alpha, \qquad \forall ~ x, ~ y \in \Omega ,
 \end{equation}
where $C(\|\rho(iT/n)\|_{L^\infty_x},  \int_{iT/n}^{(i+1)T/n} \|\nabla V \|_{{ \mathcal C  }^\alpha (\Omega)} \,d\tau)$. We combine
\eqref{eq 3 : Lemma equi-cont} and \eqref{eq 4 : Lemma equi-cont} with \eqref{eq29:Lemma:AC-curve} for $q=\infty$, and conclude \eqref{eq 2 : Holder of splitting}
which completes the proof.

\label{T:unbounded_divfree}
Let $m>1$ and $1<q \leq m+1$. Suppose that $\rho_0 \in \mathcal{P}(\mathbb{R}^d) \cap L^{q}(\mathbb{R}^d)$. Furthermore, assume that $\nabla \cdot V \geq 0$ and 
\begin{equation}\label{V_unbounded_divfree}
V\in \mathfrak{S}_{m,q}^{(q_1,q_2)} \quad \text{for} \quad
\begin{array}{l l}
\begin{cases}
 \frac{2+q_{m,d}}{1+q_{m,d}} \leq q_2 \leq \left[\frac{1}{\gamma_1} - \frac{1}{q+m-1}\right]^{-1},
 & \text{if }  1<q\leq \overline{q} , \vspace{1 mm} \\
\gamma_1 \leq q_2 \leq \left[\frac{1}{\gamma_1} - \frac{1}{q+m-1}\right]^{-1} ,
& \text{if }  \overline{q} < q \leq m+1, \vspace{1 mm} \\
\end{cases}
\text{ and } d>2,\vspace{2 mm} \\
\begin{cases}
 \frac{2+q_{m,d}}{1+q_{m,d}} \leq q_2 < \left[\frac{1}{\gamma_1} - \frac{1}{q+m-1}\right]^{-1},
 & \text{if }   1<q \leq \overline{q}, \vspace{1 mm} \\
  \gamma_1 \leq q_2 < \left[\frac{1}{\gamma_1} - \frac{1}{q+m-1}\right]^{-1},
 & \text{if }   \overline{q} < q \leq m+1, \vspace{1 mm} 
\end{cases}
 \text{ and } d=2,
\end{array}
\end{equation}
where 
\begin{equation}\label{overline_q}
\gamma_1 = \frac{d(q+m-1) + 2q}{md+q}, \ \text{ and } \ \overline{q} = \frac{1}{2}\left( \sqrt{d^2(m-1)^2 + 4} -d(m-1)+2\right).
\end{equation}
Then, there exists a nonnegative $L^q$-weak solution of  \eqref{E:Main} on $\mathbb{R}^{d}\times (0, T)$ in \cite[Definition~2.1]{HKK} that holds \eqref{T:weakSol:E_q} where $C=C(\|\rho_0\|_{L^{q}(\mathbb{R}^d)})$.

\begin{itemize}
\item[(i)] Furthermore, by applying Proposition~\ref{P:AL1}, the existence results are extended for all $q>1$ in \cite[Theorem~2.13, Theorem~2.15, \& Theorem~2.16]{HKK}. 

                                                                                                 
   
               
              
                                                                      
                                                         
                                                      
            
   

\item[(ii)] If $1< m < m^\ast$ with $m^\ast$ in \eqref{m_ast} and $1< q \leq \tilde{q}$ with
\begin{equation}\label{tilde_q}
\tilde{q} = \frac{1}{2} \left( \sqrt{d^2(m-1)^2 - 2d(m^2-1)+(3-m)^2} - d(m-1) + (3-m) \right), 
\end{equation}
then the range of $q_2$ allows $\infty$.                                            
   
            
              
                                             
                                            
                                            
                                         
            
   

\item[(iii)] Fig.~\ref{F:compact1} illustrates \eqref{V_unbounded_divfree} when $ 1 < m \leq m^\ast$  for  $m^\ast$ in \eqref{m_ast} and $1 < q \leq m+1$. Fig.~\ref{F:compact2} illustrates \eqref{V_unbounded_divfree} when $ m > m^\ast$  for  $m^\ast$ in \eqref{m_ast} and $1 < q \leq m+1$. 

\end{itemize}
